use appfw_runtime::{
    routing::runtime_graphql_schema_routes, security::SecurityConfig, RuntimeAuthState,
};
use axum::Router;
use std::sync::Arc;

use crate::data::data_access::DataAccess;
use crate::handlers::system::*;

pub async fn get_routes(
    data_access: Arc<DataAccess>,
    app_state: RuntimeAuthState,
    security: SecurityConfig,
) -> Router {
    let system_schema = async_graphql::Schema::build(
        SystemQuery::default(),
        SystemMutation::default(),
        async_graphql::EmptySubscription,
    )
    .data(data_access.clone())
    .limit_depth(security.graphql_max_depth)
    .limit_complexity(security.graphql_max_complexity)
    .finish();
    let system_introspection_schema = async_graphql::Schema::build(
        SystemQuery::default(),
        SystemMutation::default(),
        async_graphql::EmptySubscription,
    )
    .data(data_access.clone())
    .introspection_only()
    .finish();

    runtime_graphql_schema_routes(
        "/system",
        system_schema,
        system_introspection_schema,
        app_state,
        security,
    )
}
